public class KubeDataGenerator {
	private final Path output;
	private final Gson gson;
	private final Map<ResourceLocation, JsonElement> data;

	public KubeDataGenerator(Path output) {
		this.output = output;
		this.gson = new GsonBuilder().setPrettyPrinting().create();
		this.data = new HashMap<>();
	}

	public void json(ResourceLocation id, JsonElement element) {
		data.put(id, element);
	}

	public void recipe(ResourceLocation id, JsonObject recipe) {
		json(id.withPrefix("recipes/"), recipe);
	}

	public void lootTable(ResourceLocation id, JsonObject lootTable) {
		json(id.withPrefix("loot_tables/"), lootTable);
	}

	public void advancement(ResourceLocation id, JsonObject advancement) {
		json(id.withPrefix("advancements/"), advancement);
	}

	public void tag(ResourceLocation id, JsonObject tag) {
		json(id.withPrefix("tags/"), tag);
	}

	public void saveAll() throws IOException {
		for (var entry : data.entrySet()) {
			var path = output.resolve("data").resolve(entry.getKey().getNamespace())
				.resolve(entry.getKey().getPath() + ".json");
			Files.createDirectories(path.getParent());
			Files.writeString(path, gson.toJson(entry.getValue()));
		}
	}
}
